/**
 * The examples gallery: our own work for made-up brands (never a customer's), each with the exact
 * prompt and settings that made it. Generated by scripts/examples/make-examples.mjs.
 */
import data from "./examples.json";

export type ExampleKind = "image" | "remix" | "video" | "story" | "voice" | "logo";
export type Example = {
  id: string;
  kind: ExampleKind;
  brand: string;
  title: string;
  style?: string;
  mode?: string;
  tab?: string;
  short: string;
  prompt: string;
  script?: string;
  url: string;
  thumb?: string;
  width?: number;
  height?: number;
  /** Inspo Remix: the picture that was remixed. */
  before?: string;
  /** The photo the video started from (a user photo, or the first frame made in step 1). */
  input?: string;
  /** True when `input` is a still made in BlinkSpot first (the first-frame preview step). */
  firstFrame?: boolean;
  /** The prompt for that still. */
  framePrompt?: string;
  audio?: string;
  svg?: string | null;
  scenes?: Array<{ prompt: string; url: string; frame?: string; framePrompt?: string }>;
  settings: { model: string; aspect?: string; duration?: number; voice?: string; font?: string; colors?: string[]; credits: number };
  use: { href: string };
};

export const EXAMPLES = data as Example[];

export const EXAMPLE_FILTERS: Array<{ id: "all" | "image" | "video" | "logo" | "voice"; label: string; kinds: ExampleKind[] }> = [
  { id: "all", label: "All", kinds: ["image", "remix", "video", "story", "logo", "voice"] },
  { id: "image", label: "Images", kinds: ["image", "remix"] },
  { id: "video", label: "Videos", kinds: ["video", "story"] },
  { id: "logo", label: "Logos", kinds: ["logo"] },
  { id: "voice", label: "Voices", kinds: ["voice"] },
];

/** The hover preview for each way of making a video in Video Studio. */
export function wayExample(mode: string): { video: string; poster?: string } | undefined {
  const pick: Record<string, string> = { showcase: "mavuno-orbit", ugc: "sauti-creator", clothing: "kitenge-tryon", lipsync: "mavuno-lipsync", storytelling: "mkate-story" };
  const e = EXAMPLES.find((x) => x.id === pick[mode]);
  return e ? { video: e.url, poster: e.input } : undefined;
}
